mapper.select:
SELECT user_id, `year_month`, title_1, title_2, title_3,
       status, provider, failure_code, attempt_count
  FROM tbl_mission_certificate_title
 WHERE user_id = #{userId}
   AND `year_month` = #{yearMonth}

mapper.update:
UPDATE tbl_mission_certificate_title
   SET status = 'FAILED',
       failed_at = CURRENT_TIMESTAMP,
       completed_at = NULL,
       failure_code = #{failureCode}
 WHERE user_id = #{userId}
   AND `year_month` = #{yearMonth}
   AND status = 'IN_PROGRESS'
